-- Water Physicality: 3D water. Places overlay objects on the tracked fixtures and swaps their sprites;
-- Project Viewpoint draws the model bound to each sprite (media/water/package.properties, generated by
-- the pack builder, which also documents the sprite numbering used here).
--   water  : standing water in a tub or sink, one sprite per fill step
--   flow   : the tap running (a tub while it fills, a sink while someone uses it)
--   stream : a running shower (the bath mod's ShowerWater object is on the square)
-- Cost: runs every 100 ms over the few fixtures near the player; a sprite is only set when it changes;
-- nothing is drawn by Lua.

local WP = require("WaterPhysicality/WP_Core")

local Data = require("WaterPhysicality/WP_Data")

local SHOWER_WATER = "ShowerWater"           -- the bath mod's running-shower object
local SPRITE = "wp_water_%d"
local FRAMES, FRAME_MS = 4, 90
local SINK_LEVEL = 0.8                       -- how full a sink gets while its tap runs
local SINK_HOLD_MS = 700                     -- the tap keeps showing this long after the action ends
local PERIOD_MS = 100

local WPW = {}
WPW.overlays = {}       -- layer key -> { obj, sprite }
WPW.lastRun = 0
WPW.remote = {}         -- "x,y,z" of a fixture -> { mode, untilMs } for another player using it
WPW.sentTap = nil       -- "x,y,z" of the fixture this player's use was last announced for
WPW.sentMode = nil
WPW.sentAt = 0

local TAP_HEARTBEAT_MS = 1000    -- while using a fixture, tell the others this often
local TAP_REMOTE_HOLD_MS = 1500  -- ...and show their use this long after the last message

-- What a player can announce: a sink tap, or (with Lifestyle: Hobbies) filling a tub, sitting in it, showering.
local LS_HOLD_MS = { fill = 3000, use = 3000, shower = 700 }    -- how long a Lifestyle state shows after its last sign

local function tapKey(x, y, z) return x .. "," .. y .. "," .. z end

-- Tells the server (which relays it to every client) which fixture this player is using, or that they stopped
-- (mode nil).
local function announce(square, mode, now)
    if not isClient() then return end
    local key = tapKey(square:getX(), square:getY(), square:getZ())
    if mode then
        if WPW.sentTap == key and WPW.sentMode == mode and now - WPW.sentAt < TAP_HEARTBEAT_MS then return end
    elseif not WPW.sentTap then
        return
    end
    WPW.sentTap, WPW.sentMode, WPW.sentAt = mode and key or nil, mode, now
    sendClientCommand(getPlayer(), "WaterPhysicality", "tap",
        { x = square:getX(), y = square:getY(), z = square:getZ(), on = mode ~= nil, mode = mode })
end

local function onServerCommand(module, command, args)
    if module ~= "WaterPhysicality" or command ~= "tap" or type(args) ~= "table" then return end
    local key = tapKey(args.x, args.y, args.z)
    WPW.remote[key] = args.on and { mode = args.mode or "tap", untilMs = getTimestampMs() + TAP_REMOTE_HOLD_MS } or nil
end
Events.OnServerCommand.Add(onServerCommand)

local function stepOf(level)
    if level <= 0.02 then return 0 end
    if level <= 0.25 then return 1 end
    if level <= 0.5 then return 2 end
    if level <= 0.75 then return 3 end
    return 4
end

-- Data.slots[slot].w / .f / .s: first sprite number of the water steps, tap flow frames and stream frames (when it has them).
local function sprite(entry, kind, k) return string.format(SPRITE, Data.slots[entry.slot][kind] + k) end
local function has(entry, kind) return Data.slots[entry.slot][kind] ~= nil end

local function waterSprite(entry)
    if not has(entry, "w") then return nil end
    local step = stepOf(entry.level)
    if step == 0 then return nil end
    return sprite(entry, "w", step - 1)
end

-- What the player is doing with a water fixture right now, if anything.
local function usedFixture(player)
    local queue = ISTimedActionQueue and ISTimedActionQueue.getTimedActionQueue(player)
    local action = queue and queue.queue and queue.queue[1]
    if not action then return nil end
    return action.waterObject or action.sink
end

-- Lifestyle: Hobbies runs one timed action per bath or shower; its fixture object tells which fixture.
local LS_ACTIONS = {
    LSPrepareBath = { "bathObject", "fill" },
    LSUseTub = { "mainTubObj", "use" },
    LSUseShower = { "showerObject", "shower" },
}

-- The fixture object and mode ("fill", "use", "shower") of the Lifestyle action this player is running.
local function lifestyleAction(player)
    local queue = ISTimedActionQueue and ISTimedActionQueue.getTimedActionQueue(player)
    local action = queue and queue.queue and queue.queue[1]
    local spec = action and LS_ACTIONS[action.Type]
    local obj = spec and action[spec[1]]
    if not obj then return nil end
    return obj, spec[2]
end

local function onSquare(obj, square)
    local sq = obj:getSquare()
    return sq ~= nil and sq:getX() == square:getX() and sq:getY() == square:getY() and sq:getZ() == square:getZ()
end

local function flowSprite(entry, frame, used, now)
    if not has(entry, "f") then return nil end
    if entry.kind == "bathtub" then
        if entry.flowUntil and now < entry.flowUntil then return sprite(entry, "f", frame) end
    elseif entry.kind == "sink" then
        if entry.flowUntil and now < entry.flowUntil then return sprite(entry, "f", frame) end
    end
    return nil
end

local function streamSprite(entry, frame, now)
    if not (entry.shower and has(entry, "s")) then return nil end
    if entry.vanilla then
        if entry.flowUntil and now < entry.flowUntil then return sprite(entry, "s", frame) end
        return nil
    elseif entry.lifestyle then
        if entry.lsMode == "shower" and entry.lsUntil and now < entry.lsUntil then return sprite(entry, "s", frame) end
        return nil
    end
    local objects = entry.square:getObjects()
    for i = 1, objects:size() do
        if objects:get(i - 1):getName() == SHOWER_WATER then return sprite(entry, "s", frame) end
    end
    return nil
end

-- Reuse an overlay already left on the square (saved with the chunk) rather than stacking another.
local function findOverlay(square, name)
    local objects = square:getObjects()
    for i = 1, objects:size() do
        local obj = objects:get(i - 1)
        if obj:getName() == name then return obj end
    end
    return nil
end

local function removeObject(obj)
    local sq = obj and obj:getSquare()
    if sq and sq:getObjects():contains(obj) then sq:RemoveTileObject(obj) end
end

-- Still on its square? In multiplayer the server can resend a chunk and drop objects the client added.
local function alive(record, now)
    local sq = record.obj:getSquare()
    if not sq then return false end
    if now - record.checked >= 1000 then
        record.checked = now
        if not sq:getObjects():contains(record.obj) then return false end
    end
    return true
end

local loggedSprites = {}
local function logSpriteOnce(name)
    if loggedSprites[name] then return end
    loggedSprites[name] = true
    local ok, found = pcall(getSprite, name)
    print(string.format("[WaterPhysicality] sprite %s exists=%s", name, tostring(ok and found ~= nil)))
end

local function ensureOverlay(layerKey, entry, name, spriteName, quiet, now)
    local record = WPW.overlays[layerKey]
    if record and alive(record, now) then
        if record.sprite ~= spriteName then
            record.obj:setSpriteFromName(spriteName)
            if not quiet then
                print(string.format("[WaterPhysicality] %s %s: %s -> %s", entry.kind, layerKey, record.sprite, spriteName))
            end
            record.sprite = spriteName
        end
        return
    end
    logSpriteOnce(spriteName)
    local obj = findOverlay(entry.square, name)
    if obj then
        obj:setSpriteFromName(spriteName)
    else
        obj = IsoObject.new(getCell(), entry.square, spriteName)
        obj:setName(name)
        entry.square:AddSpecialObject(obj)
    end
    WPW.overlays[layerKey] = { obj = obj, sprite = spriteName, checked = now }
    print(string.format("[WaterPhysicality] %s overlay %s at %s", entry.kind, spriteName, layerKey))
end

local summaryMs = 0
local function logSummary(now)
    if now - summaryMs < 10000 then return end
    summaryMs = now
    local fixtures, overlays, kinds = 0, 0, {}
    for _, entry in pairs(WP.fixtures) do
        fixtures = fixtures + 1
        kinds[entry.kind] = (kinds[entry.kind] or 0) + 1
    end
    for _ in pairs(WPW.overlays) do overlays = overlays + 1 end
    local parts = {}
    for kind, n in pairs(kinds) do table.insert(parts, kind .. "=" .. n) end
    print(string.format("[WaterPhysicality] tracking %d fixtures (%s), %d overlays",
        fixtures, table.concat(parts, " "), overlays))
end

function WPW.sync(now)
    local tick = math.floor(now / FRAME_MS)
    local frame = tick - FRAMES * math.floor(tick / FRAMES)     -- 0..FRAMES-1 (no % on large numbers)
    local player = getPlayer()
    local used = player and usedFixture(player) or nil
    local lsObj, lsMode = nil, nil
    if player and LSUseTub ~= nil then lsObj, lsMode = lifestyleAction(player) end
    local seen = {}
    for key, entry in pairs(WP.fixtures) do
        local sqKey = tapKey(entry.square:getX(), entry.square:getY(), entry.square:getZ())
        if entry.kind == "sink" then
            -- a sink only holds water while its tap runs (someone drinks, washes or fills from it)
            local mine = entry.hasWater and used == entry.object
            local theirs = WPW.remote[sqKey]
            if mine then
                announce(entry.square, "tap", now)
                entry.flowUntil = now + SINK_HOLD_MS
            elseif theirs and now < theirs.untilMs and entry.hasWater then
                entry.flowUntil = now + SINK_HOLD_MS
            elseif WPW.sentTap == sqKey then
                announce(entry.square, nil, now)
            end
            entry.target = (entry.flowUntil and now < entry.flowUntil) and SINK_LEVEL or 0
        elseif entry.vanilla then
            -- plain game: the fixture shows water while a vanilla water action runs on it, like a sink
            local mine = entry.hasWater and used and onSquare(used, entry.square)
            local theirs = WPW.remote[sqKey]
            if mine then
                announce(entry.square, "tap", now)
                entry.flowUntil = now + SINK_HOLD_MS
            elseif theirs and now < theirs.untilMs and entry.hasWater then
                entry.flowUntil = now + SINK_HOLD_MS
            elseif WPW.sentTap == sqKey then
                announce(entry.square, nil, now)
            end
            if entry.kind == "bathtub" then
                entry.target = (entry.flowUntil and now < entry.flowUntil) and SINK_LEVEL or 0
            end
        elseif entry.lifestyle then
            -- Lifestyle: Hobbies tubs and showers hold water only while its bath / shower actions run,
            -- this player's or another player's (announced through the server)
            local mode
            if lsObj and onSquare(lsObj, entry.square) then
                mode = lsMode
                announce(entry.square, mode, now)
            else
                local theirs = WPW.remote[sqKey]
                if theirs and now < theirs.untilMs then mode = theirs.mode end
                if WPW.sentTap == sqKey then announce(entry.square, nil, now) end
            end
            if mode and LS_HOLD_MS[mode] then
                entry.lsMode, entry.lsUntil = mode, now + LS_HOLD_MS[mode]
                if mode == "fill" then entry.flowUntil = now + 400 end
            end
            if entry.kind == "bathtub" then
                local held = entry.lsUntil and now < entry.lsUntil and entry.lsMode or nil
                entry.target = (held == "fill" or held == "use") and 1 or 0
            end
        end
        local name = waterSprite(entry)
        if name then
            local layerKey = key .. "|water"
            seen[layerKey] = true
            ensureOverlay(layerKey, entry, WP.WATER_NAME, name, false, now)
        end
        name = flowSprite(entry, frame, used, now)
        if name then
            local layerKey = key .. "|flow"
            seen[layerKey] = true
            ensureOverlay(layerKey, entry, WP.FLOW_NAME, name, true, now)
        end
        name = streamSprite(entry, frame, now)
        if name then
            local layerKey = key .. "|stream"
            seen[layerKey] = true
            ensureOverlay(layerKey, entry, WP.STREAM_NAME, name, true, now)
        end
    end
    -- remove overlays whose fixture left the scan area or whose water stopped
    for layerKey, record in pairs(WPW.overlays) do
        if not seen[layerKey] then
            removeObject(record.obj)
            WPW.overlays[layerKey] = nil
            print("[WaterPhysicality] removed overlay " .. layerKey)
        end
    end
    -- overlays saved from an earlier session that no tracked fixture owns any more
    if #WP.strays > 0 then
        local owned = {}
        for _, record in pairs(WPW.overlays) do owned[record.obj] = true end
        for _, obj in ipairs(WP.strays) do
            if not owned[obj] then
                removeObject(obj)
                print("[WaterPhysicality] removed stray overlay")
            end
        end
        WP.strays = {}
    end
end

local function onTick()
    local now = getTimestampMs()
    if now - WPW.lastRun < PERIOD_MS then return end
    WPW.lastRun = now
    local ok, err = pcall(WPW.sync, now)
    if not ok then print("[WaterPhysicality] sync error: " .. tostring(err)) end
    logSummary(now)
end

Events.OnTick.Add(onTick)
print("[WaterPhysicality] water layer loaded")

return WPW
